contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;
        assert(reverted || (afterC == 0 && afterThis >= beforeThis));
    }
    receive() external payable {}
}

